   168  otError MleRouter::BecomeLeader(void)
   169  {
   170      otError  error = OT_ERROR_NONE;
   171      Router * router;
   172      uint32_t partitionId;
   173      uint8_t  leaderId;
   174
   175      VerifyOrExit(!Get<MeshCoP::ActiveDataset>().IsPartiallyComplete(), error = OT_ERROR_INVALID_STATE);
   176      VerifyOrExit(mRole != OT_DEVICE_ROLE_DISABLED, error = OT_ERROR_INVALID_STATE);
   177      VerifyOrExit(mRole != OT_DEVICE_ROLE_LEADER, error = OT_ERROR_NONE);
   178      VerifyOrExit(IsRouterRoleEnabled(), error = OT_ERROR_NOT_CAPABLE);
   179
   180      mRouterTable.Clear();
   181
   182      partitionId = mFixedLeaderPartitionId ? mFixedLeaderPartitionId : Random::NonCrypto::GetUint32();
   183
   184      leaderId = IsRouterIdValid(mPreviousRouterId) ? mPreviousRouterId
   185                                                    : Random::NonCrypto::GetUint8InRange(0, kMaxRouterId + 1);
   186
   187      SetLeaderData(partitionId, mLeaderWeight, leaderId);
   188
   189      router = mRouterTable.Allocate(leaderId);
   190      assert(router != NULL);
   191
   192      SetRouterId(leaderId);
   193      router->SetExtAddress(Get<Mac::Mac>().GetExtAddress());
   194
   195      Get<NetworkData::Leader>().Reset();
   196      Get<MeshCoP::Leader>().SetEmptyCommissionerData();
   197
   198      SetStateLeader(GetRloc16(leaderId));
   199
   200  exit:
   201      return error;
   202  }
